<section class="admin-head"><div><p class="eyebrow">FulfilmentOS · v0.7.6</p><h1>Dispatch & Installation</h1><p>Carrier booking, tracking, delivery and installation completion.</p></div></section>
<section class="admin-card"><h2>Shipments</h2><div class="table-wrap"><table><thead><tr><th>Shipment</th><th>Order</th><th>Status</th><th>Carrier</th><th>Tracking</th><th>Actions</th></tr></thead><tbody><?php foreach($shipments as $sh):$inst=fulfilment_installation_for_order($sh['order_guid']);?><tr><td><?=e($sh['number'])?></td><td><a href="<?=e(url('/admin/order/'.$sh['order_guid']))?>"><?=e($sh['order_number'])?></a></td><td><?=e($sh['status'])?></td><td><?=e($sh['carrier']??'—')?></td><td><?=e($sh['tracking_number']??'—')?></td><td><?php if(in_array($sh['status'],['READY','BOOKED'],true)):?><details><summary>Packing verification</summary><?php foreach($sh['packages'] as $pkg):?><form method="post" action="<?=e(url('/admin/fulfilment/shipment/'.$sh['guid'].'/package/'.$pkg['guid']))?>" class="stack"><?=csrf_field()?><strong><?=e($pkg['label'])?></strong><div class="admin-grid four"><label>L cm<input type="number" step="0.1" min="0" name="length_cm" value="<?=e((string)$pkg['length_cm'])?>"></label><label>W cm<input type="number" step="0.1" min="0" name="width_cm" value="<?=e((string)$pkg['width_cm'])?>"></label><label>H cm<input type="number" step="0.1" min="0" name="height_cm" value="<?=e((string)$pkg['height_cm'])?>"></label><label>Weight kg<input type="number" step="0.1" min="0" name="weight_kg" value="<?=e((string)$pkg['weight_kg'])?>"></label></div><label><input type="checkbox" name="fragile" value="1" <?=!empty($pkg['fragile'])?'checked':''?>> Fragile</label><label><input type="checkbox" name="packed_verified" value="1" <?=!empty($pkg['packed_verified'])?'checked':''?>> Packing verified</label><button class="btn outline">Save package</button></form><?php endforeach;?></details><?php endif;?><?php if($sh['status']==='READY'):?><form method="post" action="<?=e(url('/admin/fulfilment/shipment/'.$sh['guid'].'/book'))?>" class="stack"><?=csrf_field()?><input name="carrier" placeholder="Carrier" required><input name="service" placeholder="Service"><input name="tracking_number" placeholder="Tracking number" required><input name="tracking_url" placeholder="Tracking URL"><button class="btn outline">Book carrier</button></form><?php elseif($sh['status']==='BOOKED'):?><form method="post" action="<?=e(url('/admin/fulfilment/shipment/'.$sh['guid'].'/dispatch'))?>"><?=csrf_field()?><input name="note" placeholder="Dispatch note"><button class="btn primary">Confirm dispatch</button></form><?php elseif(in_array($sh['status'],['DISPATCHED','IN_TRANSIT','OUT_FOR_DELIVERY','EXCEPTION'],true)):?><form method="post" action="<?=e(url('/admin/fulfilment/shipment/'.$sh['guid'].'/transit'))?>" class="stack"><?=csrf_field()?><select name="status"><option>IN_TRANSIT</option><option>OUT_FOR_DELIVERY</option><option>DELIVERED</option><option>EXCEPTION</option></select><input name="note" placeholder="Tracking note"><button class="btn outline">Update tracking</button></form><?php else:?>Delivered<?php endif;?><?php if($inst):?><p>Installation <?=e($inst['status'])?> · <?=e($inst['scheduled_date'].' '.$inst['time_slot'])?></p><?php if($inst['status']!=='COMPLETED'):?><form method="post" action="<?=e(url('/admin/fulfilment/installation/'.$inst['guid'].'/action'))?>" class="stack"><?=csrf_field()?><input name="note" placeholder="Installation note"><button class="btn outline" name="action" value="CONFIRM">Confirm</button><button class="btn primary" name="action" value="COMPLETE">Complete</button></form><?php endif;?><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="admin-card"><h2>Orders ready for fulfilment</h2><div class="table-wrap"><table><thead><tr><th>Order</th><th>Status</th><th>Installation</th><th>Shipment</th></tr></thead><tbody><?php foreach($orders as $o):$sh=fulfilment_shipment_for_order($o['guid']);?><tr><td><a href="<?=e(url('/admin/order/'.$o['guid']))?>"><?=e($o['number'])?></a></td><td><?=e($o['status'])?></td><td><?=money((int)($o['pricing']['installation']??0))?></td><td><?=e($sh['number']??'—')?></td></tr><?php endforeach;?></tbody></table></div></section>
